INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('dc5ebe12-171d-4b44-b456-a5e190fc9080', 'Incremento de Renta', '2', NULL, 'RENTA FIJA', E'- **Years 1 to 5:**\n  - Annual Rent: $5,040,000.00 plus VAT ($150.00 per m2).\n  - Monthly Rent: Annual Rent divided by 12.\n  - Year 1 has discounts as per contract.\n  - Rent increases annually based on inflation rate (INEGI index).\n\n- **Years 6 to 10:**\n  - Annual Rent: $5,644,800.00 plus VAT ($168.00 per m2).\n  - Monthly Rent: Annual Rent divided by 12.\n  - Rent increases as per clause five from Year 7 to 10.\n\n- **Years 11 to 15:**\n  - Annual Rent: $6,316,800.00 plus VAT ($188.00 per m2).\n  - Monthly Rent: Annual Rent divided by 12.\n  - Rent increases as per clause five from Year 12 to 15.\n\n- **Years 16 to 20:**\n  - Annual Rent: $7,089,600.00 plus VAT ($211.00 per m2).\n  - Monthly Rent: Annual Rent divided by 12.\n  - Rent increases as per clause five from Year 17 to 20.\n\n- **Years 21 to 25:**\n  - Annual Rent: $7,929,600.00 plus VAT ($236.00 per m2).\n  - Monthly Rent: Annual Rent divided by 12.\n  - Rent increases as per clause five from Year 22 to 25.\n\n- **Years 26 to 30:**\n  - Annual Rent: $8,870,400.00 plus VAT ($264.00 per m2).\n  - Monthly Rent: Annual Rent divided by 12.\n  - Rent increases as per clause five from Year 27 to 30.', E'Años 1 al 5: $5,040,000.00 (cinco millones cuarenta mil pesos 00/100 M.N.) más el correspondiente Impuesto al Valor Agregado- ($150.00 pesos por m2) anual, excepto por los descuentos previstos en el contrato el primer año de Renta. Para obtener la cantidad de la Renta Mensual deberá dividirse la Renta Anual entre 12 (doce) meses. El incremento de la renta por el Año 2 al 5 será lo estipulado en clausula quinta de este contrato. ["Durante la vigencia de este Contrato, el importe de la Renta se incrementará anualmente en el mismo porcentaje de inflación (Índice Nacional de Precios al Consumidor) que indique el Instituto Nacional de Estadistica y Geografia (INEGI), correspondiente a los 12 meses inmediatos anteriores a la fecha en la que deba realizarse el incremento anual referido. Desde este momento el Arrendatario reconoce en forma expresa que dichos incrementos operarán en forma automática, sin necesidad de aviso previo. "]\n\nAños 6 al 10: $5,644,800.00 (cinco millones seiscientos cuarenta y cuatro mil ochocientos pesos 00/100 M.N.) más el correspondiente Impuesto al Valor Agregado- ($168.00 pesos por m2), anual. Para obtener la cantidad de la Renta Mensual deberá dividirse la Renta Anual entre 12 (doce) meses. El incremento de la renta por el Año 7 al 10 será lo estipulado en clausula quinta de este contrato.\n\nAños 11 al 15: $6,316,800.00 (seis millones trescientos dieciséis mil ochocientos pesos 00/100 M.N.) más el correspondiente Impuesto al Valor Agregado- ($188.00 pesos por m2), anual. Para obtener la cantidad de la Renta Mensual deberá dividirse la Renta Anual entre 12 (doce) meses. El incremento de la renta por el Año 12 al 15 será lo estipulado en clausula quinta de este contrato.\n\nAños 16 al 20: $7,089,600.00 (siete millones ochenta y nueve mil seiscientos pesos 00/100 M.N.) más cl correspondiente Impuesto al Valor Agregado- ($211.00 pesos por m2), anual. Para obtener la cantidad de la Renta Mensual deberá dividirse la Renta Anual entre 12 (doce) meses. El incremento de la renta por el Año 17 al 20 será lo estipulado en clausula quinta de este contrato.\n\nAños 21 al 25: $7,929,600.00 (siete millones novecientos veintínueve mil seiscientos pesos 00/100 M.N.) más el correspondiente Impuesto al Valor Agregado- ($236.00 pesos por m2), anual. Para obtener la cantidad de la Renta Mensual deberá dividirse la Renta Anual entre 12 (doce) meses. El incremento de la renta por el Año 22 al 25 será lo estipulado en clausula quinta de este contrato.\n\nAños 26 al 30: $8,870,400.00 (ocho millones ochocientos setenta mil cuatrocientos pesos 00/100 M.N.) más el correspondiente Impuesto al Valor Agregado- ($264.00 pesos por m2), anual. Para obtener la cantidad de la Renta Mensual deberá dividirse la Renta Anual entre 12 (doce) meses. El incremento de la renta por el Año 27 al 30 será lo estipulado en clausula quinta de este contrato.');
