INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('04c317f7-5891-4433-b665-1ef407f85541', 'Fecha de Firma del Contrato', '22 de diciembre de 2021', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04c317f7-5891-4433-b665-1ef407f85541', 'Late Fees', '7', '6', 'INTERESES EN CASO DE MORA', E'- La tasa de interés por pagos atrasados se calcula multiplicando la Tasa de Interés Interbancaria de Equilibrio (TIIE) vigente por 2.\n- Esta tasa se aplica al total de la deuda no pagada a tiempo.\n- Se cobra si el arrendatario se retrasa más de 5 días naturales después de la fecha de vencimiento.\n- La mora se cuenta desde el primer día después de la fecha de vencimiento.', 'La tasa anual de intereses moratorios resultará de multiplicar la Tasa de Interés Interbancaria de Equilibrio (TIIE) determinada por el Banco de México y que se encuentre vigente al momento de que sea exigible el pago de intereses moratorios, multiplicada por 2 (dos). Esta tasa anual de interés moratoria se aplicará sobre el importe total de adeudo no cubierto puntualmente, y será exigible cuando el Arrendatario se retrase en el pago por más de 5 (cinco) días naturales a partir de la Fecha de Vencimiento, tomando en cuenta que se contará la mora desde el primer día posterior a dicha fecha.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04c317f7-5891-4433-b665-1ef407f85541', 'Pago de Rentas', '7', '7', 'ANTICIPO', E'- The tenant must deposit an advance payment to the landlord within the first 10 days of each rental anniversary.\n- This payment should be made in immediately available funds to the account specified in the contract.\n- The advance includes the Monthly Rent plus VAT and the Maintenance Fee plus VAT.\n- The advance will cover the first, second-to-last, and last monthly rent payments of that year.\n- The Maintenance Fee must also be paid as specified in Clause Fourteen of the contract.\n- The advance payment will not earn any interest for the tenant.', 'El Arrendatario depositará durante los primeros 10 (diez) días de cada aniversario de FECHA EFECTIVA DE INICIO DE RENTA al Arrendador en fondos inmediatamente disponibles y por medio de depósito en la cuenta (referida en la Cláusula Tercera del presente Contrato) en la fecha de firma del presente Contrato de Arrendamiento, la cantidad referida en la carátula del presente Contrato, como Rentas Anticipadas, como anticipo (en lo sucesivo denominado como "Anticipo"). Dicho Anticipo será conformado por la Renta Mensual más IVA y la Cuota de Mantenimiento más IVA. El Anticipo será aplicado al pago de la primera, penúltima y última Renta Mensual de dicho aniversario, así mismo, se deberá adicionar el pago de la Cuota de Mantenimiento que indica la cláusula Décima Cuarta del presente contrato, en el entendido de que dicha cantidad no causará ningún interés a favor del Arrendatario. Por lo anterior cada aniversario de la FECHA EFECTIVA DE INICIO DE RENTA, el Arrendatario estará obligado a pagar el Anticipo el cual será aplicado cada año a la primera, penúltima y última Renta Mensual del año que corresponda.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04c317f7-5891-4433-b665-1ef407f85541', 'Incremento de Renta', '7', '5', 'INCREMENTOS A LA RENTA MENSUAL', E'- The monthly rent will increase every 12 months starting from January 1, 2023.\n- The increase will be based on 100% of the inflation rate as shown by the National Consumer Price Index (INPC).\n- If the INPC is no longer available, it will be replaced by another index from the relevant authority.\n- Annual rent increases cannot exceed 6% of the current monthly rent for the first 5 years of the contract.\n- From the 6th year onwards, annual increases cannot exceed 8% of the current monthly rent.', 'La Renta Mensual se incrementará cada vez que transcurra un periodo de 12 (doce) meses contados a partir del 01 de enero de 2023 aplicándose a las Rentas Mensuales pagaderas a partir e incluyendo el mes siguiente a dicho periodo, el 100% (cien por ciento) del porcentaje de la inflación que refleje el Índice Nacional de Precios al Consumidor (en lo sucesivo denominado como "INPC") publicado por el Banco de México y/o el Instituto Nacional de Estadística y Geografía para los 12 (doce) meses anteriores conocidos; en el entendido de que si el INPC dejare de existir, el mismo será sustituido por aquél que la autoridad competente emita para efecto de sustituirlo. En la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 6% del valor de la Renta Mensual vigente durante los primeros 5 (cinco) años de Contrato y a partir del año 6 (seis) dichos aumentos anuales no podrán ser mayores al 8% del valor de la Renta Mensual vigente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04c317f7-5891-4433-b665-1ef407f85541', 'Maintenance - Tenant', '12', '13', 'MANTENIMIENTO DEL LOCAL COMERCIAL', E'- The landlord is not responsible for maintenance, improvements, or repairs of any kind in the commercial space.\n- The tenant must keep the commercial space in excellent condition.\n- This includes maintaining both the interior and exterior parts, such as:\n  - Doors and their components\n  - Emergency exits\n  - Windows and glass\n  - Utility installations\n  - Plumbing and drainage systems within or under the floor slab, ensuring free flow to the main drainage line\n  - Fixtures\n  - Heating and air conditioning\n  - Exterior mechanical equipment servicing the space\n  - Interior walls, floors, and ceilings\n- Repairs may include replacements if necessary.', 'El Arrendador no será responsable de proveer el mantenimiento o de hacer cualquier mejora o reparación de cualquier tipo en el Local Comercial. El Arrendatario conservará y mantendrá en óptimo estado el Local Comercial y cada parte del mismo, incluyendo sin limitación las partes interiores y exteriores de todas las puertas y sus partes, salidas de emergencia, ventanas, vidrios, instalaciones de servicios públicos, instalaciones de plomería y drenaje dentro del Local Comercial o bajo la losa de piso incluyendo libre flujo a la línea principal del drenaje, accesorios, calefacción, aire acondicionado, equipos mecánicos exteriores que den servicio al Local Comercial, así como paredes interiores, pisos y cielos, en buen estado de orden, reparación y mantenimiento (cuya reparación incluirá en caso necesario reemplazos).');
