th_in_months_remaining":28,"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":57418,"grid_name":"Celta (López Mateos)","grid_full_address":"7887 Periférico Sur, A1, Santa María Tequepexpan, Tlaquepaque, Jalisco 45601","map_addr_1":"7887 Periférico Sur","map_addr_2":"A1","map_city_state_zip":"Santa María Tequepexpan, Tlaquepaque, Jalisco 45601","grid_brand":"Planet Fitness","location_created_at":"2025-09-18 16:04:01","active_lease_count_over_time":50502,"location_count_over_time":57418,"remaining_rent_liability_over_time":50502,"base_rent_current_month":"350720.0000","base_rent_next_month":"350720.0000","base_rent_per_square_meter":"1920.00","base_rent_per_year":"4208640.0000"}'::jsonb);
