ent":"4208640.0000","daily_gross_rent":"11530.52054795","recurring_rent_annual":"4208640.0000","lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"base_rent_current_month":"350720.0000","base_rent_next_month":"350720.0000","base_rent_per_square_meter":"1920.00","base_rent_per_year":"4208640.0000"}'::jsonb);
