INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('46cd37e8-7c7a-4841-96bd-758d485ebc17', 'Fecha de Apertura', '27 de diciembre de 2025', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('46cd37e8-7c7a-4841-96bd-758d485ebc17', 'Late Fees', '14', '16', 'INTERESES MORATORIOS', E'- The tenant must make all payments on time as agreed in the contract.\n- If a payment is late, a late interest rate of 2% per month will be charged.\n- This interest applies to the total unpaid amount.\n- The late interest is due if the tenant misses a payment deadline, considering any grace periods in the contract.\n- The interest is calculated monthly or for any part of a month until the payment is made.', 'La Arrendataria se obliga a cumplir con todas y cada una de las obligaciones de pago pactadas en el presente contrato, precisamente en las fechas o términos convenidos, y acepta cubrir en el caso de mora de cualquier pago los intereses moratorios que se calcularán como sigue: La tasa de intereses moratorios será del 2% (dos por ciento) mensual. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio será exigible cuando la Arrendataria se retrase en un pago en la fecha en que debió hacerlo, atendiendo a los periodos de cura contemplados en el presente Contrato. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago y hasta la liquidación del mismo.');
